<?php
namespace Modules\Shipping\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;use Illuminate\Database\Eloquent\Relations\HasOne;use Modules\Core\Models\Concerns\BelongsToCompany;use Modules\Finance\Models\ArInvoice;use Modules\MasterData\Models\Currency;use Modules\Sales\Models\SalesOrder;
class CommercialInvoice extends Model{use BelongsToCompany;public const STATUSES=['DRAFT','ISSUED','CANCELLED'];protected $fillable=['company_id','doc_no','shipment_id','sales_order_id','invoice_date','currency_id','exchange_rate','lc_number','total_amount','status','created_by','updated_by'];protected function casts():array{return['invoice_date'=>'date','exchange_rate'=>'decimal:12','total_amount'=>'decimal:4'];}public function shipment():BelongsTo{return$this->belongsTo(Shipment::class);}public function salesOrder():BelongsTo{return$this->belongsTo(SalesOrder::class);}public function currency():BelongsTo{return$this->belongsTo(Currency::class);}public function lines():HasMany{return$this->hasMany(CommercialInvoiceLine::class);}public function arInvoice():HasOne{return$this->hasOne(ArInvoice::class);}}
